public.enqueue_current_report:
CREATE OR REPLACE FUNCTION public.enqueue_current_report(p_establishment uuid, p_organization uuid, p_user uuid, p_language text, p_request uuid, p_legacy_model text, p_legacy_version integer)
 RETURNS historical_report_runs
 LANGUAGE plpgsql
 SET search_path TO ''
 SET jit TO 'off'
AS $function$
declare r public.historical_report_runs;q public.report_generation_requests;e text;jt text;begin
 if exists(select 1 from private.retired_generation_keys where request_id=p_request) then raise exception 'REPORT_REQUEST_RETIRED';end if;
 if exists(select 1 from public.review_corpus_policy where paused) then raise exception 'RETENTION_TRANSITION_ACTIVE';end if;
 if exists(select 1 from private.retention_rebuild_requests) and not exists(select 1 from private.retention_rebuild_requests where request_id=p_request) then raise exception 'RETENTION_TRANSITION_ACTIVE';end if;
 if exists(select 1 from public.review_corpus_policy where enabled) then perform pg_advisory_xact_lock(hashtextextended('recent-text-corpus:'||p_establishment::text,0));end if;
 if current_user<>'service_role' or p_request is null or p_language not in('fr','vi')
 or not exists(select 1 from public.establishments where id=p_establishment and organization_id=p_organization and active)
 or not exists(select 1 from public.organization_members where organization_id=p_organization and user_id=p_user and role in('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 perform pg_advisory_xact_lock(hashtextextended('historical-enqueue:'||p_establishment::text||':'||p_language,0));
 select * into q from public.report_generation_requests where id=p_request;
 if q.id is not null then
  if q.organization_id<>p_organization or q.establishment_id<>p_establishment or q.authority_user_id<>p_user or q.language<>p_language then raise exception 'FORBIDDEN';end if;
  if exists(select 1 from public.report_generation_abandonments a where a.request_id=q.id) then raise exception 'REPORT_REQUEST_ABANDONED_NEW_ID_REQUIRED';end if;
  select * into r from public.historical_report_runs where id=q.source_run_id;return r;
 end if;
 select * into r from public.historical_report_runs where establishment_id=p_establishment and language=p_language and status in('queued','running','retry') order by created_at desc limit 1;
 if r.id is not null then return r;end if;
 if exists(select 1 from public.analysis_parallel_reports pair join public.analysis_jls_sol_ready_operations op on op.run_id=pair.run_id
 where pair.organization_id=p_organization and pair.establishment_id=p_establishment and pair.language=p_language and op.request_count=1 and (op.status='billing_uncertain' or op.receipt is null)) then raise exception 'REPORT_PREVIOUS_OUTCOME_UNCERTAIN';end if;
 if exists(select 1 from public.analysis_parallel_reports pair join public.analysis_jls_restaurant_runs j on j.id=pair.run_id where pair.establishment_id=p_establishment and pair.language=p_language and j.status in('queued','running')) then raise exception 'REPORT_OTHER_PIPELINE_RUNNING';end if;
 if exists(select 1 from public.analysis_jev_batch_runs br join public.analysis_parallel_reports bp on bp.id=br.report_id where br.current_source_run_id is not null and bp.establishment_id=p_establishment and bp.language=p_language and not exists(select 1 from public.report_generation_abandonments a where a.source_run_id=br.current_source_run_id) and (br.status='billing_uncertain' or exists(select 1 from public.analysis_jev_batch_tasks bt where bt.run_id=br.id and bt.status='unknown'))) then raise exception 'REPORT_PREVIOUS_OUTCOME_UNCERTAIN';end if;
 select engine,jev_transport into e,jt from public.report_pipeline_settings where id for share;
 if e='jev_sol_v2' then
  insert into public.historical_report_runs(organization_id,establishment_id,language,requested_by,status,snapshot,model)
  values(p_organization,p_establishment,p_language,p_user,'queued',case when exists(select 1 from public.review_corpus_policy where enabled) then public.freeze_recent_review_source(p_establishment,p_organization,p_language,now()) else '{"analysis_version":8,"analysis_text_policy":"account_google_or_original_v1"}'::jsonb end, 'gpt-6.1-sol') returning * into r;
 else
  if exists(select 1 from public.historical_report_runs where establishment_id=p_establishment and language=p_language and error_code='REPORT_BILLING_UNCERTAIN_NO_RETRY') then raise exception 'REPORT_BILLING_UNCERTAIN_NO_RETRY';end if;
  r=public.enqueue_historical_report(p_establishment,p_organization,p_user,p_language,p_legacy_model,p_legacy_version);
 end if;
 insert into public.report_generation_requests(id,organization_id,establishment_id,authority_user_id,language,engine,source_run_id,jev_transport) values(p_request,p_organization,p_establishment,p_user,p_language,e,r.id,case when e='jev_sol_v2' then jt else 'individual' end);return r;
end $function$

public.freeze_recent_review_source:
CREATE OR REPLACE FUNCTION public.freeze_recent_review_source(p_establishment uuid, p_organization uuid, p_language text, p_as_of timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p public.review_corpus_policy;rows jsonb;overrides jsonb;meta jsonb;e jsonb;begin
 if current_user<>'service_role' then raise exception 'FORBIDDEN';end if;
 select * into p from public.review_corpus_policy where id for share;
 if p.paused or not p.enabled then raise exception 'RETENTION_TRANSITION_ACTIVE';end if;
 perform pg_advisory_xact_lock(hashtextextended('recent-text-corpus:'||p_establishment::text,0));
 perform private.apply_recent_review_retention(p_establishment,p_as_of);
 select jsonb_build_object('id',id,'organization_id',organization_id,'name',name,'rating',(select avg(rating) from public.reviews where establishment_id=p_establishment),'total_reviews',(select count(*) from public.reviews where establishment_id=p_establishment),'created_at',created_at) into e from public.establishments where id=p_establishment and organization_id=p_organization;
 if e is null then raise exception 'FORBIDDEN';end if;
 select jsonb_agg(jsonb_build_object('id',r.id,'external_review_id',r.external_review_id,'rating',r.rating,'original_text',case when public.review_usable_text(r.original_text,r.text) is null then null else coalesce(nullif(r.original_text,''),r.text) end,'original_language',r.original_language,'text',case when public.review_usable_text(r.original_text,r.text) is null then null else r.text end,'published_at',r.published_at,
  'historical_import',r.historical_import,'has_negative_feedback',r.has_negative_feedback,'status',r.status,'review_detailed_rating',r.review_detailed_rating,'review_context',r.review_context,
  'ai_status',r.ai_status,'ai_suggested_reply',r.ai_suggested_reply,'ai_suggested_reply_language',r.ai_suggested_reply_language,'reply_draft_text',r.reply_draft_text,'reply_draft_language',r.reply_draft_language,
  'review_translations',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'language',t.language,'translated_text',t.translated_text,'source_text_sha256',t.source_text_sha256,'created_at',t.created_at,'updated_at',t.updated_at) order by t.language) from public.review_translations t where t.review_id=r.id),'[]'),
  'review_reply_drafts',coalesce((select jsonb_agg(jsonb_build_object('language',d.language,'ai_status',d.ai_status,'draft_text',d.draft_text,'ai_suggested_reply',d.ai_suggested_reply)) from public.review_reply_drafts d where d.review_id=r.id),'[]')) order by r.id),
  jsonb_build_object('epoch',p.epoch,'version',p.version,'as_of',p_as_of,'cutoff',null,'review_count',count(*),'period_start',min(r.published_at),'period_end',max(r.published_at),
   'review_ids',jsonb_agg(r.id order by r.id),'fingerprint',public.review_corpus_fingerprint(p_establishment)) into rows,meta
 from public.reviews r where r.establishment_id=p_establishment and r.id in(select public.retained_review_ids(p_establishment,p_as_of));
 if rows is null then raise exception 'NO_REVIEWS_AVAILABLE';end if; if not exists(select 1 from public.reviews where establishment_id=p_establishment and public.review_usable_text(original_text,text) is not null) then raise exception 'NO_TEXT_REVIEWS_AVAILABLE';end if;
 
 return jsonb_build_object('analysis_version',8,'analysis_text_policy','account_google_or_original_v1','retention',meta,'retention_frozen_rows',rows,'retention_establishment',e);
end $function$

private.store_current_report_publication:
CREATE OR REPLACE FUNCTION private.store_current_report_publication(p jsonb, sc jsonb, p_created_at timestamp with time zone, p_recovery boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare doc jsonb;bindings jsonb;ev jsonb;meta jsonb;is_stale boolean;s record;changed integer;
begin
 if p->>'state' is distinct from 'completed' or p#>>'{controls,technical_checks_passed}' is distinct from 'true'
 or p#>'{derived_report,report}' is null or p->>'generated_at' is null or sc->>'source_run_id' is distinct from p->>'current_source_run_id'
 or sc->>'establishment_id' is distinct from p->>'establishment_id' or sc->>'organization_id' is distinct from p->>'organization_id'
 or p_created_at is null then raise exception 'PUBLICATION_SOURCE_INVALID';end if;
 perform pg_advisory_xact_lock(hashtextextended('recent-text-corpus:'||(p->>'establishment_id'),0));
 is_stale=coalesce((sc->>'stale')::boolean,false) or sc->>'fingerprint' is distinct from public.review_corpus_fingerprint((p->>'establishment_id')::uuid);
 is_stale=is_stale or not exists(select 1 from public.review_corpus_policy where enabled and not paused and epoch::text=sc->>'policy_epoch'); if not p_recovery and not exists(select 1 from public.historical_report_runs where id=(p->>'current_source_run_id')::uuid and establishment_id=(p->>'establishment_id')::uuid and organization_id=(p->>'organization_id')::uuid and language=p->>'language') then raise exception 'PUBLICATION_TENANT_OR_LANGUAGE_CHANGED';end if; if is_stale and not p_recovery and not private.shared_jev_frozen_allowed((p->>'current_source_run_id')::uuid) then return false;end if;
 select coalesce(jsonb_agg(x),'[]') into bindings from (
  select jsonb_build_object('id',r->>'id','rating',r->'rating','published_at',r->'published_at','analysis_language',r->'analysis_language',
   'original_language',coalesce(r->'original_language',r#>'{translation_provenance,original_language}'),'analysis_source',r->'analysis_source','translation_provenance',r->'translation_provenance','review_detailed_rating',r->'review_detailed_rating','review_context',private.recommendation_spend_context_v1(r->'review_context'),
   'analysis_text_sha256',coalesce(r->>'analysis_text_sha256',encode(extensions.digest(coalesce(r->>'analysis_text',''),'sha256'),'hex')),
   'original_text_sha256',coalesce(r->>'original_text_sha256',encode(extensions.digest(coalesce(r->>'original_text',''),'sha256'),'hex'))) x
  from jsonb_array_elements(p->'source_reviews') r) t;
 if jsonb_array_length(bindings)<>(sc->>'review_count')::int then raise exception 'PUBLICATION_BINDINGS_INCOMPLETE';end if;
 select coalesce(jsonb_agg(jsonb_build_object('evidence_id',e->>'evidence_id','review_id',e->>'review_id','category',e->>'category','polarity',e->>'polarity','quote_sha256',e->>'quote_sha256')),'[]') into ev from jsonb_array_elements(p#>'{controls,evidence}') e;
 select coalesce(jsonb_object_agg(k,v),'{}') into meta from jsonb_each(case when jsonb_typeof(p->'source_report')='object' then p->'source_report' else '{}'::jsonb end) x(k,v)
 where k in('generation_id','ai_status','stored_reviews_count','preferred_language','sample_average_rating','food_average','food_review_count','service_average','service_review_count','atmosphere_average','atmosphere_review_count','customer_rating_statistics','analysis_input_stats');
 doc=jsonb_build_object('id',p->'id','current_source_run_id',p->'current_source_run_id','reference_generation_id',p->'reference_generation_id','state','completed','error_code',null,
  'created_at',p->'created_at','generated_at',p->'generated_at','configuration_version',p->'configuration_version','derived_report',private.publication_generated_report(p->'derived_report'),
  'original_report',null,'raw_response',null,'corrections',null,'source_report',meta,'source_reviews','[]'::jsonb,'statistics',p->'statistics','usage',p->'usage',
  'controls',jsonb_build_object('technical_checks_passed',true,'section_issues','[]'::jsonb,'semantic_correctness_guaranteed',false,'dated_publication',true));
 insert into public.current_report_publications(establishment_id,organization_id,language,report_id,source_run_id,source_created_at,generated_at,scope,document,source_bindings,evidence_bindings,stale,stale_reason,provenance)
 values((p->>'establishment_id')::uuid,(p->>'organization_id')::uuid,p->>'language',(p->>'id')::uuid,(p->>'current_source_run_id')::uuid,p_created_at,(p->>'generated_at')::timestamptz,sc,doc,bindings,ev,is_stale,case when is_stale then 'CORPUS_CHANGED' end,
  jsonb_build_object('method',case when p_recovery then 'saved_response_dated_recovery' else 'validated_current_publication' end,'provider_calls',0))
 on conflict(establishment_id,language) do update set report_id=excluded.report_id,source_run_id=excluded.source_run_id,source_created_at=excluded.source_created_at,
  generated_at=excluded.generated_at,scope=excluded.scope,document=excluded.document,source_bindings=excluded.source_bindings,evidence_bindings=excluded.evidence_bindings,
  stale=excluded.stale,stale_reason=excluded.stale_reason,provenance=excluded.provenance,updated_at=now()
 where current_report_publications.report_id<>excluded.report_id and (excluded.source_created_at,excluded.source_run_id)>(current_report_publications.source_created_at,current_report_publications.source_run_id);
 get diagnostics changed=row_count;
 if changed>0 then
  for s in select old.current_source_run_id from public.analysis_parallel_reports old join public.historical_report_runs src on src.id=old.current_source_run_id
   where old.establishment_id=(p->>'establishment_id')::uuid and old.language=p->>'language' and old.state='completed'
   and (src.created_at,src.id)<(p_created_at,(p->>'current_source_run_id')::uuid)
   loop perform private.retention_retire_source(s.current_source_run_id,'SUPERSEDED_REPORT');end loop;
 end if;
 return changed>0;
end $function$
